report_script:
f = filters or {}
if not f.get("company"):
    f["company"] = frappe.db.get_single_value("Global Defaults", "default_company")
if not f.get("from_date"):
    f["from_date"] = frappe.utils.get_first_day(frappe.utils.today())
if not f.get("to_date"):
    f["to_date"] = frappe.utils.today()
std = frappe.get_doc("Report", "Customer Ledger Summary")
data = std.execute_script_report(f)

filters = filters or {}
short = {"Payment Promised": "Promised", "Partial Payment": "Partial"}
rows = frappe.db.sql("""SELECT recovery_status AS status,
        SUM(outstanding_amount) AS outstanding
    FROM `tabLedgerLift Tracker`
    WHERE recovery_status != 'Paid'
    GROUP BY recovery_status ORDER BY outstanding DESC""", as_dict=1)
out = []
for r in rows:
    nm = short.get(r["status"] or "", r["status"] or "(none)")
    if len(nm) > 12:
        nm = nm[:11] + "…"
    val = frappe.utils.flt(r["outstanding"])
    if val > 0:
        out.append({"status": nm, "outstanding": val})
