    ],
    onload: function(report) {
        report.page.add_inner_button(__("New Purchase Order"), function() {
            var rows = (report.data || []).filter(function(r) { return r.po_item && r.po_qty > 0 && !r.indent; });
            if (!rows.length) { frappe.msgprint(__("Nothing to order")); return; }
            var d = new frappe.ui.Dialog({
                title: __("Create Draft Purchase Order"),
                fields: [
                    { fieldname: "supplier", label: __("Supplier"), fieldtype: "Link", options: "Supplier", reqd: 1 },
                    { fieldname: "scope", label: __("Include"), fieldtype: "Select",
                      options: ["Only items usually bought from this supplier", "All items needing order"],
                      default: "Only items usually bought from this supplier" }
                ],
                primary_action_label: __("Create"),
                primary_action: function(v) {
                    var take = rows;
                    if (v.scope.indexOf("Only") === 0) {
                        take = rows.filter(function(r) { return (r.suppliers || "").indexOf(v.supplier) >= 0; });
                    }
                    if (!take.length) { frappe.msgprint(__("No reorder rows list this supplier - choose All items")); return; }
                    var items = take.map(function(r) { return { item_code: r.po_item, qty: r.po_qty }; });
                    d.hide();
                    frappe.call({
                        method: "stockpilot_make_po",
                        args: { supplier: v.supplier, items: JSON.stringify(items) },
                        freeze: true,
                        callback: function(r) {
                            if (r.message) { frappe.set_route("Form", "Purchase Order", r.message); }
                        }
                    });
                }
            });
            d.show();
        });
    },
    initial_depth: 0,
    formatter: function (value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);
        if (data && data.bold_row && column.fieldname === "label") {
