frappe.query_reports["StockPilot Stock Audit"] = {
    filters: [
        {fieldname: "issue", label: __("Issue"), fieldtype: "Select",
         options: ["All", "Negative stock", "Missing pool key"], default: "All"}
    ]
};

report_script:
filters = filters or {}
issf = filters.get("issue") or "All"

today = frappe.utils.nowdate()

items = frappe.db.sql(
    "select i.name as code, i.item_name as iname, i.item_group as igrp, "
    "ifnull(i.pd_pesticide_technical_name, '') as tn, "
    "ifnull(i.pd_seed_crop_family, '') as cf, "
    "ifnull(i.pd_fertilizer_grade, '') as gr, "
    "ifnull(i.pd_manufacturer, '') as mfr "
    "from `tabItem` i where i.is_stock_item = 1 and i.disabled = 0",
    as_dict=1)
imap = {}
for it in items:
    imap[it.code] = it

COMPANY = "Vijay Agro Centre"  # multi-company site: scope to VAC (review C4/H10)
bins = frappe.db.sql(
    "select b.item_code as code, sum(b.actual_qty) as q, sum(b.stock_value) as v "
    "from `tabBin` b join `tabWarehouse` w on w.name = b.warehouse "
    "where w.company = %s group by b.item_code", (COMPANY,), as_dict=1)
onh = {}
onv = {}
for b in bins:
    onh[b.code] = frappe.utils.flt(b.q)
    onv[b.code] = frappe.utils.flt(b.v)

d365 = frappe.utils.add_days(today, -365)
s12 = frappe.db.sql(
    "select sii.item_code as code, sum(sii.stock_qty) as q "
    "from `tabSales Invoice Item` sii "
    "join `tabSales Invoice` si on si.name = sii.parent "
    "where si.docstatus = 1 and si.company = %s and si.posting_date >= %s "
    "group by sii.item_code", (COMPANY, d365), as_dict=1)
q12 = {}
for s in s12:
    q12[s.code] = frappe.utils.flt(s.q)

lin = frappe.db.sql(
    "select item_code as code, max(posting_date) as d from `tabStock Ledger Entry` "
    "where is_cancelled = 0 and actual_qty > 0 group by item_code", as_dict=1)
lastin = {}
for r in lin:
    lastin[r.code] = r.d
lout = frappe.db.sql(
    "select item_code as code, max(posting_date) as d from `tabStock Ledger Entry` "
    "where is_cancelled = 0 and actual_qty < 0 group by item_code", as_dict=1)
lastout = {}
for r in lout:
    lastout[r.code] = r.d

gtot = {}
gkey = {}
for it in items:
    gtot[it.igrp] = frappe.utils.cint(gtot.get(it.igrp)) + 1
    if it.tn or it.cf or it.gr:
        gkey[it.igrp] = frappe.utils.cint(gkey.get(it.igrp)) + 1
pooledgrp = {}
for g in gtot:
    if gtot[g] >= 3 and frappe.utils.cint(gkey.get(g)) * 2 >= gtot[g]:
        pooledgrp[g] = 1

cols = [
    {"label": "Issue", "fieldname": "issue", "fieldtype": "Data", "width": 150},
    {"label": "Item", "fieldname": "item", "fieldtype": "Link", "options": "Item", "width": 240},
    {"label": "Group", "fieldname": "igrp", "fieldtype": "Data", "width": 150},
    {"label": "On Hand", "fieldname": "on_hand", "fieldtype": "Float", "width": 90},
    {"label": "Stock Value", "fieldname": "stock_value", "fieldtype": "Currency", "width": 110},
    {"label": "12-mo Sold Qty", "fieldname": "qty12", "fieldtype": "Float", "width": 110},
    {"label": "Last In", "fieldname": "last_in", "fieldtype": "Date", "width": 95},
    {"label": "Last Out", "fieldname": "last_out", "fieldtype": "Date", "width": 95},
    {"label": "Note", "fieldname": "note", "fieldtype": "Data", "width": 380},
]

negrows = []
for code in onh:
    if onh[code] >= -0.0005:
        continue
    it = imap.get(code)
    igrp = ""
    if it:
        igrp = it.igrp
    if lastin.get(code) is None:
        note = "Never received in ERPNext - opening balance likely missing; count and set via Stock Reconciliation"
    else:
        note = "Oversold vs book - received qty under-recorded or billing hit the wrong item; verify then count"
    negrows.append([onv.get(code, 0.0), {
        "issue": "Negative stock", "item": code, "igrp": igrp,
        "on_hand": onh[code], "stock_value": frappe.utils.flt(onv.get(code)),
        "qty12": frappe.utils.flt(q12.get(code)),
        "last_in": lastin.get(code), "last_out": lastout.get(code),
        "note": note}])
negrows = sorted(negrows, key=lambda x: x[0])

keyrows = []
for it in items:
    if it.tn or it.cf or it.gr:
        continue
    if it.igrp not in pooledgrp:
        continue
    oh = frappe.utils.flt(onh.get(it.code))
    qq = frappe.utils.flt(q12.get(it.code))
    note = "No technical name / grade in a pooled group - fill Product Details"
    if not it.mfr:
        note = note + "; NO manufacturer either - possible duplicate item, consider merge/disable"
    keyrows.append([0.0 - qq, {
        "issue": "Missing pool key", "item": it.code, "igrp": it.igrp,
        "on_hand": oh, "stock_value": frappe.utils.flt(onv.get(it.code)),
        "qty12": qq, "last_in": lastin.get(it.code),
        "last_out": lastout.get(it.code), "note": note}])
keyrows = sorted(keyrows, key=lambda x: x[0])

rows = []
if issf in ("All", "Negative stock"):
    for pair in negrows:
        rows.append(pair[1])
if issf in ("All", "Missing pool key"):
    for pair in keyrows:
        rows.append(pair[1])

negval = 0.0
for pair in negrows:
    negval = negval + frappe.utils.flt(pair[0])
message = ("%d negative-stock items (book value %s) | %d items missing their pool key "
           "in pooled groups | fix path: count physically, post ONE Stock Reconciliation "
           "(Phase 0), fill Product Details for missing keys") % (
    len(negrows), frappe.utils.fmt_money(negval), len(keyrows))

data = [cols, rows, message, None, None, 1]

